#![allow(unused_imports)]
use verus::*;

verus! {
    /// Given an integer `n` in [1, 1998], returns a Vec<char> of length 3:
    ///  - ['A', 'B', 'C'] if `n < 1000`
    ///  - ['A', 'B', 'D'] if `n >= 1000`
    fn solve(n: i32) -> Vec<char>
        requires 1 <= n && n <= 1998,
        ensures   result.len() == 3,
        ensures result[0] == 'A',
        ensures result[1] == 'B',
        ensures (n < 1000  ==> result[2] == 'C'),
        ensures (n >= 1000 ==> result[2] == 'D')
    {
        let mut v: Vec<char> = Vec::new();
        // first two characters
        v.push('A');
        v.push('B');
        // third character based on the value of n
        if n < 1000 {
            v.push('C');
        } else {
            v.push('D');
        }
        v
    }

    proof fn solve_tests() {
        // some basic checks
        assert!(solve(1)    == ['A', 'B', 'C'].to_vec());
        assert!(solve(500)  == ['A', 'B', 'C'].to_vec());
        assert!(solve(999)  == ['A', 'B', 'C'].to_vec());
        assert!(solve(1000) == ['A', 'B', 'D'].to_vec());
        assert!(solve(1500) == ['A', 'B', 'D'].to_vec());
        assert!(solve(1998) == ['A', 'B', 'D'].to_vec());
    }
}